insert into public.series(id,project_id,name,international_name,bible,age_range,target_age_min,target_age_max,status,visual_style) values ('a2746bb2-96da-50d2-a433-c0a61207b2da','a2b6d64a-08a0-474f-b7c0-fa71121b00ab','WonderlyTales: Titokváros','Titokvaros','Egy térkép-restaurátor vidra és valószínűtlen barátai rájönnek, hogy városuk eltűnő utcái egy elfeledett árvízvédelmi gépezet részei — és valaki úgy akarja megmenteni a belvárost, hogy mások otthonát törli le a térképről.','8+',8,99,'DEVELOPMENT','eredeti filmes 3D, Rigify, natív Blender') on conflict(id) do nothing;
insert into public.seasons(id,series_id,season_number,number,title,arc,status) values('587a0966-2776-5d7b-acb3-06ed9323b94f','a2746bb2-96da-50d2-a433-c0a61207b2da',1,1,'Az elfeledett város','Egy város attól marad otthon, hogy senkit nem tekint fölöslegesnek. Bizalom: a bizonyosság hiánya nem jogosít fel arra, hogy mások helyett döntsünk.','DEVELOPMENT') on conflict(id) do nothing;
insert into public.episodes(id,season_id,episode_number,number,title,target_duration_sec,language,master_language,brief,story_brief,script_version,status) values('732d0fd0-151a-595c-acca-d802a5624dd1','587a0966-2776-5d7b-acb3-06ed9323b94f',1,1,'A város titka',3600,'hu','hu','Az áramszünetek alatt eltűnő Rézrakpart utcát Mira a régi térképen keresi. Brúnóval és Kippel megállítanak egy elszabadult rakodókocsit, majd a zsilipáramkörben szándékos vezérlést találnak.','{"number": 1, "title": "A város titka", "duration_target": 3600, "adventure": "Az áramszünetek alatt eltűnő Rézrakpart utcát Mira a régi térképen keresi. Brúnóval és Kippel megállítanak egy elszabadult rakodókocsit, majd a zsilipáramkörben szándékos vezérlést találnak.", "emotion": "Mira elfogadja, hogy segítséget kérni nem gyengeség.", "resolution": "A negyed éjszakai kiürítését és a katasztrofális vízbetörést megállítják; a lakók hazajutnak.", "season_clue": "Egy járat, amelyen a hivatalos menetrend szerint húsz éve nem ment vonat, ma éjjel áramot vett fel."}','TV_V001','DEVELOPMENT') on conflict(id) do nothing;
insert into public.episodes(id,season_id,episode_number,number,title,target_duration_sec,language,master_language,brief,story_brief,script_version,status) values('5e81ff40-4241-54b3-a23c-b8e341933561','587a0966-2776-5d7b-acb3-06ed9323b94f',2,2,'Az elveszett vonat',3600,'hu','hu','Egy üres szerelvény mindig ugyanakkor tér vissza, eggyel kevesebb kocsival. A csapat a mozgó műhelyvasút alatt rekedt karbantartókat menti ki.','{"number": 2, "title": "Az elveszett vonat", "duration_target": 3600, "adventure": "Egy üres szerelvény mindig ugyanakkor tér vissza, eggyel kevesebb kocsival. A csapat a mozgó műhelyvasút alatt rekedt karbantartókat menti ki.", "emotion": "Brúnó és Tilda régi szakítása; a felelősség megosztása.", "resolution": "Az elveszett szerelvény és utasai előkerülnek. Az üresnek hitt kocsik terhet szállítanak a gátrendszerbe.", "season_clue": "A régi műhely menetrendje hat csomópontot nevez meg, a hatodikat lekaparták."}','TV_V001','DEVELOPMENT') on conflict(id) do nothing;
insert into public.episodes(id,season_id,episode_number,number,title,target_duration_sec,language,master_language,brief,story_brief,script_version,status) values('0fc4402d-d690-55c3-bae6-3350e1296ec8','587a0966-2776-5d7b-acb3-06ed9323b94f',3,3,'Az éjszakai negyed',3600,'hu','hu','Fényjelek jelennek meg a lezárt gáttestben. A hősök betörőkre gyanakodnak, de egy elszigetelt karbantartóközösség kér segítséget.','{"number": 3, "title": "Az éjszakai negyed", "duration_target": 3600, "adventure": "Fényjelek jelennek meg a lezárt gáttestben. A hősök betörőkre gyanakodnak, de egy elszigetelt karbantartóközösség kér segítséget.", "emotion": "Kipp megkülönbözteti a félelmet az előítélettől, Néra először vállalja nyilvánosan a bizonyítékát.", "resolution": "Helyreáll a két negyed kapcsolata, a fények segélykérése érthetővé válik.", "season_clue": "Áron aláírása szerepel a régi kiürítési jegyzőkönyvön; az egyik utca soha nem kapott visszatérési engedélyt."}','TV_V001','DEVELOPMENT') on conflict(id) do nothing;
insert into public.episodes(id,season_id,episode_number,number,title,target_duration_sec,language,master_language,brief,story_brief,script_version,status) values('e611aa15-5a9e-54db-bc08-f191741fc834','587a0966-2776-5d7b-acb3-06ed9323b94f',4,4,'A nagy verseny',3600,'hu','hu','Az egész városon átvezető futárverseny alatt a pályaterelések elfedik az árvízi kapcsolók szállítását. Oszkárnak a dobogó és társai biztonsága között kell döntenie.','{"number": 4, "title": "A nagy verseny", "duration_target": 3600, "adventure": "Az egész városon átvezető futárverseny alatt a pályaterelések elfedik az árvízi kapcsolók szállítását. Oszkárnak a dobogó és társai biztonsága között kell döntenie.", "emotion": "A győzelem és a megbízhatóság konfliktusa.", "resolution": "A verseny célba ér, a veszélyes terelést leállítják; Oszkár elveszíti az első helyet, de megmenti a futárok hírnevét.", "season_clue": "Nem egyetlen hibás kapuról van szó: valaki átrendezi a teljes rendszer vízútját."}','TV_V001','DEVELOPMENT') on conflict(id) do nothing;
insert into public.episodes(id,season_id,episode_number,number,title,target_duration_sec,language,master_language,brief,story_brief,script_version,status) values('69cf0d7f-0a7a-59d0-8248-af5c93e70dcc','587a0966-2776-5d7b-acb3-06ed9323b94f',5,5,'A titkos térkép',3600,'hu','hu','A csapat több tervrétegből állítja össze a város régi tervrajzát. Az igazság közzététele pánikot is okozhat, miközben a vihar közelít.','{"number": 5, "title": "A titkos térkép", "duration_target": 3600, "adventure": "A csapat több tervrétegből állítja össze a város régi tervrajzát. Az igazság közzététele pánikot is okozhat, miközben a vihar közelít.", "emotion": "Mira apja nem hibátlan hős; Áron bocsánatkérés helyett vállalható tényeket ad.", "resolution": "A terv nyilvános és érthető lesz, a közösségek valódi kiürítési tervet kapnak.", "season_clue": "Az utolsó kapu két oldalát egyszerre kell nyitni; a biztos terve csak egy oldalt tart fenn."}','TV_V001','DEVELOPMENT') on conflict(id) do nothing;
insert into public.episodes(id,season_id,episode_number,number,title,target_duration_sec,language,master_language,brief,story_brief,script_version,status) values('809f8ed2-8211-5b14-b84f-9066dc4b29e0','587a0966-2776-5d7b-acb3-06ed9323b94f',6,6,'Az utolsó kapu',3600,'hu','hu','A viharban minden hős saját negyedében vezet mentést. A kaput csak a korábban elvágott közösségek együttműködése nyitja biztonságosan.','{"number": 6, "title": "Az utolsó kapu", "duration_target": 3600, "adventure": "A viharban minden hős saját negyedében vezet mentést. A kaput csak a korábban elvágott közösségek együttműködése nyitja biztonságosan.", "emotion": "A nyolc különálló képesség közös döntéssé válik. Vera elismeri a tervét és kiadja a hiányzó műszaki adatot.", "resolution": "A város megmenekül, a titkos lezárások oka napvilágra kerül; felelős nyilvános helyreállítás kezdődik, nincs következmény nélküli megbocsátás.", "season_clue": "Az évad központi rejtélye lezárul. Egy folyón túli jeladó új helyet ígér, nem teszi semmissé a lezárást."}','TV_V001','DEVELOPMENT') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('2f0eb3f6-0953-598e-8dad-e6cc0a6963a0','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_MIRA','Mira','eurázsiai vidra','CORE','CORE','nő','24 éves','{"code": "MIRA", "name": "Mira", "species": "eurázsiai vidra", "age": 24, "gender": "nő", "height_m": 1.68, "color": "#C58B32", "appearance": "Kis kerek fülek, csokoládébarna szőr, világos krémszínű pofa, borostyánszem, vastag elvékonyodó farok. Rövid okker esőkabát, petrol nadrág, barna bakancs, térképtok.", "job": "térkép-restaurátor", "personality": "Kíváncsi, gyors eszű, empatikus; idegen helyen magabiztosnak tetteti magát.", "strength": "Térbeli emlékezet; észreveszi, ha egy városrész fizikailag nem fér el a tervrajzon.", "weakness": "Fél beismerni, hogy a neki fontos dolgokról is tévedhet. Előbb ugrik, aztán kér segítséget.", "motivation": "Bizonyítani akarja, hogy apja megőrzött régi térképei valódi lakóhelyeket rögzítenek.", "arc": "A magányos bizonyítótól a felelősséget és döntést megosztó csapatvezetőig.", "movement": "Hajlékony gerinc, alacsony forduló, a farok késleltetett ellensúly; futásnál teljes talajkontaktus, nem csúszó lábak.", "face": "Apró félmosoly, eltérő szemöldökmagasság, döntés előtt rövid szemlesütés; a pofa és az állkapocs külön vezérelt.", "voice": "Magyar női mezzo, 24 körüli hangkor, enyhén levegős mélység, világos mássalhangzók. Gyors gondolkodás, lassú őszinte vallomás. Nem gyerekhang.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"BRUNO": "A biztonságról vitatkoznak, később egymás vakfoltjait védik.", "KIPP": "Nem hősiességet követel tőle, hanem pontos megfigyelést.", "NERA": "Gyerekkori barátból elhallgatás miatt bizalmi ellenfél.", "ARON": "Apja egykori munkatársa; Mira nem fogadja el helyette a hallgatást."}}'::jsonb,'Kis kerek fülek, csokoládébarna szőr, világos krémszínű pofa, borostyánszem, vastag elvékonyodó farok. Rövid okker esőkabát, petrol nadrág, barna bakancs, térképtok.','Magyar női mezzo, 24 körüli hangkor, enyhén levegős mélység, világos mássalhangzók. Gyors gondolkodás, lassú őszinte vallomás. Nem gyerekhang.','DESIGN') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('45d26413-7b23-522d-b90c-793c61cd3578','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_BRUNO','Brúnó','európai borz','CORE','CORE','férfi','38 éves','{"code": "BRUNO", "name": "Brúnó", "species": "európai borz", "age": 38, "gender": "férfi", "height_m": 1.78, "color": "#33455F", "appearance": "Zömök, széles váll, felismerhető hosszanti fehér-fekete arccsíkok; rövid fülek. Indigó munkáskertésznadrág, krém ing, rézszínű szerszámöv, nehéz bakancs.", "job": "villamos- és fékszerelő", "personality": "Száraz humorú, megbízható, látszólag mogorva. Félbehagyott javítást nem tud otthagyni.", "strength": "Terhelést, rezgést és fékhibát testből ért; válságban is pontos.", "weakness": "Egy régi baleset után minden kockázatot személyes kudarcnak vesz; túl későn delegál.", "motivation": "Senki ne sérüljön meg az ő műszakjában.", "arc": "A mindent egyedül megtartó munkástól a másokban bízó mentorhoz.", "movement": "Súly a sarkakon, mozdulat előtt terhelésváltás; futása rövid, erős lépésekből áll.", "face": "Visszafogott szemjáték, késleltetett mosoly; félelemben inkább szorítja a száját.", "voice": "Meleg magyar bariton, 38–45-ös hangkor; kissé érdes, nem mesemondó. Száraz mondatvégek, akcióban hallható légzés.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"MIRA": "Megtanulja, hogy a kíváncsiság nem felelőtlenség.", "TILDA": "Korábbi tanítványával szakmai sértettségük ellenére összeillenek.", "DORKA": "Régi kikötői barát, aki kimondja, amit ő elhallgat.", "KIPP": "Ösztönösen óvja, majd valódi felelősséget bíz rá."}}'::jsonb,'Zömök, széles váll, felismerhető hosszanti fehér-fekete arccsíkok; rövid fülek. Indigó munkáskertésznadrág, krém ing, rézszínű szerszámöv, nehéz bakancs.','Meleg magyar bariton, 38–45-ös hangkor; kissé érdes, nem mesemondó. Száraz mondatvégek, akcióban hallható légzés.','DESIGN') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('2733bd73-05cd-59e2-b0b2-23bfbf4223b0','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_KIPP','Kipp','egyiptomi repülőkutya','CORE','CORE','férfi','19 éves','{"code": "KIPP", "name": "Kipp", "species": "egyiptomi repülőkutya", "age": 19, "gender": "férfi", "height_m": 1.35, "color": "#82A78E", "appearance": "Nagy hegyes fülek, mogyoróbarna szőr és szem, keskeny felnőtt alkat. Mentazöld ujjatlan technikusmellény szárnynyílással, grafit nadrág, nyakban fejhallgató. A szárnyhártya a megnyúlt kar- és ujjcsontokhoz kapcsolódik.", "job": "színházi hangtechnikus-tanonc", "personality": "Félénk, hallására figyelő, furcsán pontos humorú; fontos helyzetben néha túl sokat beszél.", "strength": "Kivételes hangmagasság- és ritmusemlékezet; különbséget tesz géphiba és szándékos jel között.", "weakness": "Nem szeret magasban átrepülni, ha mások nézik; túlelemzi a saját hibáit.", "motivation": "Azt szeretné, hogy figyeljenek arra, amit hall, ne csak arra, hogy megijed.", "arc": "A láthatatlanságra törekvő segédtől a döntő pillanatban megszólaló társért felelős felnőttig.", "movement": "Kis feszes lépések, fül előbb fordul, fej utána. Karhoz simuló hártya; futásnál nem lebeg merev szárnylap.", "face": "Élénk fülek, tekintetváltás, nyelés; bátorság közben is látható félelem.", "voice": "Fiatal magyar férfi tenor, természetes, tiszta és enyhén rekedő izgalomban. Nem héliumos komikus hang.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"MIRA": "Mira meghallgatja; ez többet ér a bátorításnál.", "BRUNO": "A szerelő eleinte kisgyerekként védi, majd egyenrangú társává válik.", "OSZKAR": "A futár ugratása mögött valódi barátság van.", "NERA": "Megtanítja neki, hogyan kérdezzen jókor."}}'::jsonb,'Nagy hegyes fülek, mogyoróbarna szőr és szem, keskeny felnőtt alkat. Mentazöld ujjatlan technikusmellény szárnynyílással, grafit nadrág, nyakban fejhallgató. A szárnyhártya a megnyúlt kar- és ujjcsontokhoz kapcsolódik.','Fiatal magyar férfi tenor, természetes, tiszta és enyhén rekedő izgalomban. Nem héliumos komikus hang.','DESIGN') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('cbdb8391-dea7-5ac0-8841-c83cc5d3f5e9','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_NERA','Néra','nyest','CORE','CORE','nő','29 éves','{"code": "NERA", "name": "Néra", "species": "nyest", "age": 29, "gender": "nő", "height_m": 1.59, "color": "#775D87", "appearance": "Karcsú barna test, hófehér torokfolt, hosszú puha farok; szilvaszínű mellény, világos ing, karcsú keretes szemüveg.", "job": "városi levéltáros", "personality": "Rendezett, ironikus, intelligens, társaságban óvatos.", "strength": "Forráskritika, nyelvek, hamisítás felismerése.", "weakness": "A munkája megtartásáért néha elhallgatja az igazságot.", "motivation": "Megőrizni a város emlékezetét úgy, hogy a családja megélhetését se veszítse el.", "arc": "A csendes őrzőtől a névvel vállalt tanúságtevőig.", "movement": "Pontos, takarékos kéz; idegességben a farka jelez helyette.", "face": "Szájzugból indított humor, sokatmondó félrenézés.", "voice": "Magyar női alt, 30 körüli hangkor, művelt és meleg, finom irónia.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"MIRA": "Régi barátság, amelyet az akták visszatartása próbára tesz.", "ARON": "Segít neki a tanúvallomást tényszerűen megfogalmazni.", "TILDA": "A rend és a szétszórtság komikus párosa."}}'::jsonb,'Karcsú barna test, hófehér torokfolt, hosszú puha farok; szilvaszínű mellény, világos ing, karcsú keretes szemüveg.','Magyar női alt, 30 körüli hangkor, művelt és meleg, finom irónia.','DESIGN') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('8534560a-3af5-5026-895f-0496ec295388','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_DORKA','Dorka','kapibara','CORE','CORE','nő','46 éves','{"code": "DORKA", "name": "Dorka", "species": "kapibara", "age": 46, "gender": "nő", "height_m": 1.88, "color": "#B9684B", "appearance": "Nagy, tömör alkat, szögletes tompa pofa, apró fülek; rozsdavörös vízálló kabát, sötét kantáros nadrág, mentőgyűrű-jelvény.", "job": "kikötői mentőhajó kapitánya", "personality": "Nyugodt, gyakorlatias, barátságos; a leghangosabb káoszban beszél a leghalkabban.", "strength": "Vízismeret, mentés, közösségszervezés.", "weakness": "Másokat támogatva a saját veszteségét nem dolgozza fel.", "motivation": "A kikötői közösség maradjon otthonában és biztonságban.", "arc": "Elfogadja, hogy neki is jár segítség; a mentésből közös döntéshozatal lesz.", "movement": "Nyugodt lendület, biztos széles alátámasztás; vízben könnyű, szárazon súlyos.", "face": "Halk együttérzés; ritka haragja visszafogott és erős.", "voice": "Magyar női mély alt, 45–50-es hangkor, telt és lassú; semmi karikírozott akcentus.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"BRUNO": "Régi barát, akinek a bűntudatát érti.", "MIRA": "Nem engedi, hogy a nyomozás megelőzze a mentést.", "ARON": "Közös emlékük a régi kiürítés, eltérő következtetésekkel."}}'::jsonb,'Nagy, tömör alkat, szögletes tompa pofa, apró fülek; rozsdavörös vízálló kabát, sötét kantáros nadrág, mentőgyűrű-jelvény.','Magyar női mély alt, 45–50-es hangkor, telt és lassú; semmi karikírozott akcentus.','DESIGN') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('f29cdf3a-54d1-550a-96bd-a8a0cc3ce6f5','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_ARON','Áron','szürke daru','CORE','CORE','férfi','57 éves','{"code": "ARON", "name": "Áron", "species": "szürke daru", "age": 57, "gender": "férfi", "height_m": 2.05, "color": "#D3C8AC", "appearance": "Hosszú nyak, hamuszürke toll, sötét csőr, vörös fejtetőfolt; homokszínű vasutaszakó, kopott zsebóra. Szárnykarok és háromujjú markolók stilizált következetes anatómiával.", "job": "nyugdíjas forgalomirányító", "personality": "Komoly, udvarias, hallgatag; váratlanul jó utánzó.", "strength": "A régi jelrendszer és az elfeledett város ismerete.", "weakness": "Húsz éve úgy véd egy ígéretet, hogy közben fenntart egy hazugságot.", "motivation": "Ne ismétlődjön meg a múltbeli rossz kiürítési döntés.", "arc": "A szégyenből őrzött titkot vállalt felelősséggé alakítja.", "movement": "Hosszú, pontos lépések; nyaka külön késéssel követi a testet; stresszben mozdulatlanná válik.", "face": "Csőrnyitás és torokmozgás; érzelmet szemhéj, fejdőlés, tolltartás közvetít.", "voice": "Magyar férfi basszbariton, 55–60-as hangkor, világos beszéd, sokat jelentő szünetek.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"MIRA": "Ismerte az apját, de nem mindent mond el róla.", "NERA": "Segít neki a tényeket a magyarázkodástól elválasztani.", "KIPP": "A fiú hallása felismeri az általa eltitkolt jelzést."}}'::jsonb,'Hosszú nyak, hamuszürke toll, sötét csőr, vörös fejtetőfolt; homokszínű vasutaszakó, kopott zsebóra. Szárnykarok és háromujjú markolók stilizált következetes anatómiával.','Magyar férfi basszbariton, 55–60-as hangkor, világos beszéd, sokat jelentő szünetek.','DESIGN') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('cc299a50-e504-53e9-aac9-c9dbb51c298a','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_TILDA','Tilda','óriás tobzoska','CORE','CORE','nő','31 éves','{"code": "TILDA", "name": "Tilda", "species": "óriás tobzoska", "age": 31, "gender": "nő", "height_m": 1.62, "color": "#4F8F94", "appearance": "Rézbarna egymásra fekvő pikkelyek, hosszú ívelt farok, finom pofa; türkiz műhelykötény, csuklóra fordítható nagyító, puha talpbetét a karmoknak.", "job": "mechanikai feltaláló és javítóműhely-tulajdonos", "personality": "Különc, örömteli, zárkózott a személyes témákban.", "strength": "Térben látja a gépet; kevés alkatrészből tartós javítást készít.", "weakness": "A gépeket hamarabb megkérdezi, mi bajuk, mint a barátait.", "motivation": "Megmutatni, hogy a régi rendszer javítható, nem csak lecserélhető.", "arc": "Elmagyarázza és megosztja a tudását, ahelyett hogy nélkülözhetetlenné tenné magát.", "movement": "Farok mint ellensúly; pikkelyek hajlatban rétegesen csúsznak, nem gumibőrként nyúlnak.", "face": "Kis szemek finom játéka, orrbillentés, szemöldök helyett szemhéj és fejdőlés.", "voice": "Magyar női középfekvés, 30-as hangkor, gyors szakmai magyarázat, emberközeli, nem robotikus.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"BRUNO": "Volt mesterével mindketten úgy érzik, a másik nem hallgatta meg őket.", "NERA": "Közös precizitásuk eltérően néz ki.", "KIPP": "A hangjaiból felismeri, melyik alkatrész hibás."}}'::jsonb,'Rézbarna egymásra fekvő pikkelyek, hosszú ívelt farok, finom pofa; türkiz műhelykötény, csuklóra fordítható nagyító, puha talpbetét a karmoknak.','Magyar női középfekvés, 30-as hangkor, gyors szakmai magyarázat, emberközeli, nem robotikus.','DESIGN') on conflict(id) do nothing;
insert into public.characters(id,series_id,code,name,species,role_type,type,gender,age_description,personality,visual_description,speech_style,status) values('630ed3ce-dd2c-5111-ae74-9194443a8156','a2746bb2-96da-50d2-a433-c0a61207b2da','TV_OSZKAR','Oszkár','vörös mókus','CORE','CORE','férfi','27 éves','{"code": "OSZKAR", "name": "Oszkár", "species": "vörös mókus", "age": 27, "gender": "férfi", "height_m": 1.48, "color": "#8C3549", "appearance": "Vörös szőr, pamacsos fülek, nagy zászlós farok; bordó futárdzseki, törtfehér sisak, oldalt merev csomagtartó.", "job": "kerékpáros futár és amatőr városi versenyző", "personality": "Vicces, hiú, bátor; szereti, ha mindenki őt nézi.", "strength": "Gyors útvonalválasztás, helyismeret, emberek helyett állatlakók mozgósítása.", "weakness": "A tapsért néha előbb vállal feladatot, mint hogy tudná, teljesíthető-e.", "motivation": "A családi futárszolgálatot megmenteni a városi kiszorítástól.", "arc": "A látványos győzelemnél fontosabbá válik, kit juttat célba.", "movement": "Ruganyos, de tömeg- és kontaktushelyes; a farok nem takarja a partner arcát.", "face": "Nagy mosoly mögötti aggodalom; hibája után nem rögtön viccel.", "voice": "Magyar férfi középfekvés, 25–30-as hangkor, mosolygós, ritmikusan gyors, drámában lelassul.", "voice_provider_id": null, "voice_status": "CASTING_PENDING", "relations": {"KIPP": "Tréfából kezdett barátság, amelyben megtanul csendben is jelen lenni.", "MIRA": "Rivalizáló helyismeret; együtt pontosabbak.", "DORKA": "Ő ismeri a családi gondját, nem hagyja bohóckodni helyette."}}'::jsonb,'Vörös szőr, pamacsos fülek, nagy zászlós farok; bordó futárdzseki, törtfehér sisak, oldalt merev csomagtartó.','Magyar férfi középfekvés, 25–30-as hangkor, mosolygós, ritmikusan gyors, drámában lelassul.','DESIGN') on conflict(id) do nothing;
